class Solution {
public:
    int maxTwoEvents(vector<vector<int>>& events) {
        int n = events.size();
        sort(events.begin(), events.end(), [](const vector<int>& a, const vector<int>& b) {
            return a[0] < b[0];
        });
        vector<int> suffixMax(n);
        suffixMax[n - 1] = events[n - 1][2];
        for (int i = n - 2; i >= 0; --i) {
            suffixMax[i] = max(suffixMax[i + 1], events[i][2]);
        }
        int ans = suffixMax[0]; // best single event
        for (int i = 0; i < n; ++i) {
            int lo = i + 1, hi = n;
            while (lo < hi) {
                int mid = (lo + hi) / 2;
                if (events[mid][0] > events[i][1]) {
                    hi = mid;
                } else {
                    lo = mid + 1;
                }
            }
            if (lo < n) {
                ans = max(ans, events[i][2] + suffixMax[lo]);
            }
        }
        return ans;
    }
};
